//! Stream and sample tables generated by `tools/gen_tables.py` from the re3 (GTA III) and reVC
//! (Vice City) reverse-engineered sources. Only facts (file names and the game's identifiers for
//! them) are taken; see `docs/SUPPORT.md` for the exact source revisions.

mod iii_pc_sfx_names;
mod iii_pc_streams;
mod iii_ps2_streams;
mod vc_pc_sfx_names;
mod vc_pc_streams;
mod vc_ps2_streams;

pub use iii_pc_sfx_names::III_PC_SFX_NAMES;
pub use iii_pc_streams::III_PC_STREAMS;
pub use iii_ps2_streams::III_PS2_STREAMS;
pub use vc_pc_sfx_names::VC_PC_SFX_NAMES;
pub use vc_pc_streams::VC_PC_STREAMS;
pub use vc_ps2_streams::VC_PS2_STREAMS;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StreamCategory {
    Radio,
    PoliceAmbience,
    Announcements,
    Cutscenes,
    MusicCues,
    MissionAudio,
}

#[derive(Debug, Clone, Copy)]
pub struct StreamDef {
    /// Path as the game opens it, `/`-separated.
    pub path: &'static str,
    /// The game's identifier for the stream (eStreamedSounds).
    pub id: &'static str,
    pub category: StreamCategory,
}

/// PS2 `.VB` streams play at 32 kHz except these, which `IsThisTrackAt16KHz` sets to 16 kHz
/// (re3: RADIO_CHAT; reVC: RADIO_KCHAT, RADIO_VCPR, RADIO_POLICE).
pub fn vb_rate(game: ef_core::Game, id: &str) -> u32 {
    let low: &[&str] = match game {
        ef_core::Game::Gta3 => &["STREAMED_SOUND_RADIO_CHAT"],
        ef_core::Game::ViceCity => {
            &["STREAMED_SOUND_RADIO_KCHAT", "STREAMED_SOUND_RADIO_VCPR", "STREAMED_SOUND_RADIO_POLICE"]
        }
        ef_core::Game::Gta1
        | ef_core::Game::Gta2
        | ef_core::Game::London1969
        | ef_core::Game::London1961
        | ef_core::Game::SanAndreas => &[],
    };
    if low.contains(&id) { 16000 } else { 32000 }
}

/// `.VB` streams are opened as stereo for every track (`CVbFile` default `nChannels = 2`).
pub const VB_CHANNELS: u16 = 2;
